    der: ['Hysteresis: energy lost each cycle in reversing the domains, ∝ area of the B–H loop ∝ <i>B</i><sub>m</sub><sup>1.6</sup> (Steinmetz), and ∝ <i>f</i> (cycles per second).', 'Eddy currents: induced EMF ∝ <i>f B</i><sub>m</sub>, loss ∝ EMF² ∝ <i>f</i>²<i>B</i><sub>m</sub>² <i>t</i>² (laminations reduce <i>t</i>).', 'At constant <i>V</i>/<i>f</i> (constant <i>B</i><sub>m</sub>): <i>P</i><sub>h</sub> ∝ <i>f</i>, <i>P</i><sub>e</sub> ∝ <i>f</i>². At constant <i>V</i>: <i>B</i><sub>m</sub> ∝ 1/<i>f</i>, so <i>P</i><sub>e</sub> does not depend on <i>f</i> and <i>P</i><sub>h</sub> ∝ <i>f</i><sup>−0.6</sup>.'],
    g: [{ n: 'Losses vs load', xl: 'Load (% of rated)', yl: 'Loss (W)', f: v => { const xs = LX.range(0, 125, 51); return { xs, ser: [{ n: 'Core loss (constant)', ys: xs.map(() => v.Pi) }, { n: 'Copper loss', ys: xs.map(x => v.Pc0 * (x / 100) ** 2) }], vl: [[v.xm, 'max η']], mark: [v.x, [v.Pi, v.Pcu]] }; } }, { x: 'f', y: ['Ph', 'Pe'], n: 'Core losses vs frequency (voltage fixed)' }],
    fig: (v, t, G) => { const m = Math.max(v.Ph, v.Pe, v.Pcu, 1), bar = (x, val, c, l) => `<rect x="${x}" y="${(220 - 160 * val / m).toFixed(1)}" width="70" height="${(160 * val / m).toFixed(1)}" rx="6" fill="${c}"/>` + G.t(x + 35, 240, l, { a: 'middle', w: 700 }) + G.t(x + 35, (212 - 160 * val / m).toFixed(1), `${fp(val)} W`, { a: 'middle', s: 12 });
      return G.svg(560, 260, G.ln(60, 220, 520, 220, 'var(--gline)') + bar(90, v.Ph, 'var(--ring1)', 'Hysteresis') + bar(210, v.Pe, 'var(--ring2)', 'Eddy') + bar(330, v.Pcu, 'var(--ring3)', 'Copper') + G.t(460, 80, `Core ${fp(v.Pi)} W`, { a: 'middle', w: 800 }) + G.t(460, 102, 'constant with load', { a: 'middle', s: 11, c: 'gv' }) + G.t(460, 140, `Cu ${fp(v.Pcu)} W`, { a: 'middle', w: 800 }) + G.t(460, 162, '∝ load²', { a: 'middle', s: 11, c: 'gv' }), 'Bar chart of hysteresis, eddy-current and copper losses'); },
    cn: { w: 'Two kinds of loss: core (iron) loss, which depends on voltage and frequency and is there whenever the transformer is energised; and copper loss, which depends on the load current.', y: 'Core loss comes from magnetising the steel back and forth (hysteresis) and from currents induced in the steel itself (eddy currents). Copper loss is I²R in the windings.', s: ['Find the flux ratio from V/f.', 'Scale P_h with f·B^1.6 and P_e with f²·B².', 'Scale copper loss with load².', 'Maximum efficiency where copper loss = core loss.'], a: 'Distribution transformers are designed with low core loss because they are energised all day even at light load (all-day efficiency).', mk: ['Thinking core loss changes with load — it does not (V and f fixed).'], sc: ['Max efficiency when P_cu = P_i, at x = √(P_i/P_cu,FL).', 'Constant V, change f: eddy loss unchanged, hysteresis loss falls as f rises.'] },
    rel: [['x', 'Pcu', 'Copper loss ∝ (load current)².'], ['x', 'Pi', 'Core loss depends on V and f only, not on the load.'], ['f', 'Pe', 'At a fixed voltage B ∝ 1/f, so P_e ∝ f² B² stays the same.'], ['f', 'Ph', 'At a fixed voltage P_h ∝ f × (1/f)^1.6 = f^−0.6: it falls as f rises.'], ['Vp', 'Pi', 'B ∝ V: both hysteresis and eddy losses rise with voltage.']],
    num: [{ a: 'xm', g: ['Ph0', 'Pe0', 'Pc0'], d: { Vp: 100, f: 50, x: 100 }, n: { Ph0: [100, 200, 300, 400], Pe0: [100, 200, 300], Pc0: [400, 800, 1000, 1600] }, mk: [['use P_i/P_cu without the root', v => 100 * v.Pi / v.Pc0], ['use √(P_cu/P_i)', v => 100 * Math.sqrt(v.Pc0 / v.Pi)]] }, { a: 'Pe', g: ['Pe0', 'f'], d: { Vp: 100 }, lv: 3, n: { Pe0: [100, 200, 400], f: [25, 40, 60, 100] }, mk: [['scale with f² ignoring the change of flux', v => v.Pe0 * (v.f / 50) ** 2], ['scale with f', v => v.Pe0 * v.f / 50]] }],
    cmp: [{ n: '50 Hz vs 60 Hz at the same voltage', a: { f: 50 }, b: { f: 60 } }, { n: 'Same V/f: 100 % at 50 Hz vs 120 % at 60 Hz', a: { Vp: 100, f: 50 }, b: { Vp: 120, f: 60 } }],
    ck: [[{ Ph0: 300, Pe0: 200, Pc0: 800, Vp: 100, f: 50, x: 100 }, { Ph: 300, Pe: 200, Pi: 500, Pcu: 800, xm: 79.057 }, 'rated conditions'], [{ Ph0: 300, Pe0: 200, Vp: 120, f: 60 }, { Ph: 360, Pe: 288 }, 'constant V/f: P_h ∝ f, P_e ∝ f²']],
