    steps: (v, f) => [['Power factor', 'cos φ₀ = <i>W</i>₀/(<i>V</i>₀<i>I</i>₀)', `${f(v.W0)} / (${f(v.V0)} × ${f(v.I0)})`, v.pf0, ''], ['Core-loss current', '<i>I</i><sub>w</sub> = <i>I</i>₀ cos φ₀', `${f(v.I0)} × ${f(v.pf0)}`, v.Iw, 'A'], ['Magnetising current', '<i>I</i><sub>µ</sub> = <i>I</i>₀ sin φ₀', `${f(v.I0)} × ${f(Math.sin(Math.acos(v.pf0)))}`, v.Imu, 'A'], ['Core-loss resistance', '<i>R</i>₀ = <i>V</i>₀/<i>I</i><sub>w</sub>', `${f(v.V0)} / ${f(v.Iw)}`, v.R0, 'Ω'], ['Magnetising reactance', '<i>X</i>₀ = <i>V</i>₀/<i>I</i><sub>µ</sub>', `${f(v.V0)} / ${f(v.Imu)}`, v.X0, 'Ω']],
    der: ['With the secondary open, only the no-load current flows; it is 2–5 % of rated current, so copper loss is negligible and <i>W</i>₀ ≈ core loss.', '<i>W</i>₀ = <i>V</i>₀<i>I</i>₀ cos φ₀ → cos φ₀; then resolve <i>I</i>₀ into <i>I</i><sub>w</sub> and <i>I</i><sub>µ</sub>.', 'Done on the LV side because rated LV voltage is easier to supply and measure; the values are then referred to the LV side.'],
    g: [{ x: 'W0', y: ['R0'], n: 'R₀ vs wattmeter reading' }, { x: 'I0', y: ['X0'], n: 'X₀ vs no-load current' }],
    fig: (v, t, G) => bench(G, true, v.V0, v.I0, v.W0),
    cn: { w: 'Apply rated voltage to one winding with the other open. The small current that flows only magnetises the core and supplies its losses — so the wattmeter reads the core loss.', y: 'At rated voltage the flux is at its rated value, so the core loss is the same as in service; the current is tiny, so copper loss is negligible.', s: ['Read V₀, I₀, W₀.', 'cos φ₀ = W₀/(V₀I₀).', 'I_w = I₀ cos φ₀, I_µ = I₀ sin φ₀.', 'R₀ = V₀/I_w, X₀ = V₀/I_µ.'], a: 'Finding core loss and the shunt branch for efficiency calculations without loading a large transformer.', mk: ['Treating W₀ as copper loss.', 'Doing the OC test on the HV side (needs a very high supply).'], sc: ['OC test → core loss + R₀, X₀ (LV side).', 'No-load pf is low, about 0.1–0.3.'] },
    rel: [['W0', 'R0', 'More wattmeter reading means a larger core-loss current, so a SMALLER R₀ = V₀/I_w.'], ['W0', 'pf0', 'cos φ₀ = W₀/(V₀I₀).'], ['I0', 'X0', 'With W₀ fixed, a larger I₀ means a larger magnetising current, so a smaller X₀.']],
    num: [{ a: 'R0', g: ['V0', 'I0', 'W0'], n: { V0: [200, 230, 250, 400], I0: [0.5, 0.7, 1, 1.2], W0: [40, 50, 70, 80, 100] }, mk: [['use V₀/I₀', v => v.V0 / v.I0], ['use V₀²/W₀ with the wrong voltage', v => v.W0 / (v.I0 * v.I0)]] }, { a: 'X0', g: ['V0', 'I0', 'W0'], lv: 3, n: { V0: [200, 230, 250], I0: [0.7, 1, 1.2], W0: [50, 70, 80] }, mk: [['use V₀/I₀', v => v.V0 / v.I0], ['use V₀/I_w', v => v.V0 / v.Iw]] }],
