    i: [['Vsc', 'Voltmeter V_sc', 'V', 15, 1, 2000, 0.1], ['Isc', 'Ammeter I_sc', 'A', 10, 0.1, 500, 0.1], ['Wsc', 'Wattmeter W_sc', 'W', 85, 1, 20000, 1], ['Ifl', 'Rated current on this side', 'A', 10, 0.1, 500, 0.1]],
    o: [['Ze', 'Equivalent impedance Z_e', 'Ω', v => v.Vsc / v.Isc], ['Re', 'Equivalent resistance R_e', 'Ω', v => v.Wsc / (v.Isc * v.Isc)], ['Xe', 'Equivalent reactance X_e', 'Ω', v => v.Ze >= v.Re ? Math.sqrt(v.Ze * v.Ze - v.Re * v.Re) : NaN], ['pfsc', 'SC power factor', '', v => v.Wsc / (v.Vsc * v.Isc), 4], ['Pcufl', 'Full-load copper loss', 'W', v => v.Wsc * (v.Ifl / v.Isc) ** 2]],
