    steps: (v, f) => [['Impedance', '<i>Z</i><sub>e</sub> = <i>V</i><sub>sc</sub>/<i>I</i><sub>sc</sub>', `${f(v.Vsc)} / ${f(v.Isc)}`, v.Ze, 'Ω'], ['Resistance', '<i>R</i><sub>e</sub> = <i>W</i><sub>sc</sub>/<i>I</i><sub>sc</sub>²', `${f(v.Wsc)} / ${f(v.Isc)}²`, v.Re, 'Ω'], ['Reactance', '<i>X</i><sub>e</sub> = √(<i>Z</i><sub>e</sub>² − <i>R</i><sub>e</sub>²)', `√(${f(v.Ze)}² − ${f(v.Re)}²)`, v.Xe, 'Ω'], ['Full-load copper loss', '<i>P</i><sub>cu,FL</sub> = <i>W</i><sub>sc</sub>(<i>I</i><sub>FL</sub>/<i>I</i><sub>sc</sub>)²', `${f(v.Wsc)} × (${f(v.Ifl)}/${f(v.Isc)})²`, v.Pcufl, 'W']],
    der: ['With the secondary shorted, only a small voltage is needed to drive rated current through the winding impedance.', 'The flux is proportional to that small voltage, so core loss ≈ 0 and <i>W</i><sub>sc</sub> = <i>I</i><sub>sc</sub>²<i>R</i><sub>e</sub>.', '<i>Z</i><sub>e</sub> = <i>V</i><sub>sc</sub>/<i>I</i><sub>sc</sub>, <i>X</i><sub>e</sub> = √(<i>Z</i><sub>e</sub>² − <i>R</i><sub>e</sub>²).'],
    g: [{ x: 'Isc', y: ['Pcufl'], n: 'Scaled full-load copper loss vs test current' }],
    fig: (v, t, G) => bench(G, false, v.Vsc, v.Isc, v.Wsc),
    cn: { w: 'Short the LV winding and slowly raise the HV voltage until rated current flows. Only a few per cent of rated voltage is needed; the wattmeter reads the copper loss at that current.', y: 'The low voltage means low flux, so core loss is negligible; the full rated current flows, so the copper loss is the full-load value.', s: ['Read V_sc, I_sc, W_sc.', 'Z_e = V_sc/I_sc, R_e = W_sc/I_sc².', 'X_e = √(Z_e² − R_e²).', 'Scale the copper loss to rated current if needed.'], a: 'Finding the % impedance (which decides fault current and parallel-sharing) and full-load copper loss.', mk: ['Applying rated voltage with the secondary shorted — a dead short; only 5–10 % voltage is used.'], sc: ['SC test → copper loss + R_e, X_e (HV side).', '% impedance = V_sc/V_rated × 100.'] },
    rel: [['Wsc', 'Re', 'R_e = W_sc/I_sc²: more loss at the same current means more resistance.'], ['Vsc', 'Ze', 'Z_e = V_sc/I_sc.'], ['Wsc', 'Xe', 'With Z_e fixed, a larger R_e leaves a smaller X_e = √(Z_e² − R_e²).']],
    num: [{ a: 'Xe', g: ['Vsc', 'Isc', 'Wsc'], n: { Vsc: [10, 12, 15, 20, 25], Isc: [5, 10, 20], Wsc: [40, 60, 85, 100, 150] }, mk: [['use Z_e + R_e', v => v.Ze + v.Re], ['use Z_e − R_e', v => v.Ze - v.Re]] }, { a: 'Re', g: ['Isc', 'Wsc'], n: { Isc: [5, 10, 20], Wsc: [40, 60, 85, 100] }, mk: [['use W/I (not squared)', v => v.Wsc / v.Isc]] }],
    cmp: [{ n: 'Test at half vs full current', a: { Isc: 5, Vsc: 7.5, Wsc: 21.25 }, b: { Isc: 10, Vsc: 15, Wsc: 85 } }],
