    me: ['eta', 'Po', 'xm', 'etam'],
    steps: (v, f) => [['Output', '<i>P</i><sub>o</sub> = <i>x S</i> cos φ', `${f(v.x / 100)} × ${f(v.S / 1e3)} × ${f(v.pf)}`, v.Po / 1e3, 'kW'], ['Copper loss', '<i>x</i>² <i>P</i><sub>cu,FL</sub>', `${f(v.x / 100)}² × ${f(v.Pc / 1e3)}`, v.Pcu / 1e3, 'kW'], ['Efficiency', 'η = <i>P</i><sub>o</sub>/(<i>P</i><sub>o</sub> + <i>P</i><sub>i</sub> + <i>x</i>²<i>P</i><sub>cu</sub>)', `${f(v.Po / 1e3)} / (${f(v.Po / 1e3)} + ${f(v.Pi / 1e3)} + ${f(v.Pcu / 1e3)})`, v.eta, '%'], ['Maximum efficiency at', '<i>x</i> = √(<i>P</i><sub>i</sub>/<i>P</i><sub>cu,FL</sub>)', `√(${f(v.Pi / 1e3)}/${f(v.Pc / 1e3)})`, v.xm, '%']],
    der: ['η = output/(output + losses). Copper loss varies as <i>x</i>², core loss is fixed.', 'dη/d<i>x</i> = 0 gives <i>x</i>²<i>P</i><sub>cu,FL</sub> = <i>P</i><sub>i</sub>: maximum efficiency when variable loss = constant loss.'],
