    fig: (v, t, G) => { const tot = v.Po + v.Pi + v.Pcu || 1, w = 480, a = w * v.Po / tot, b = w * v.Pi / tot, c = w * v.Pcu / tot;
      return G.svg(560, 220, G.t(40, 40, 'Where the input power goes', { w: 800 }) + `<rect x="40" y="60" width="${a.toFixed(1)}" height="50" rx="6" fill="var(--ring3)"/><rect x="${(40 + a + 2).toFixed(1)}" y="60" width="${Math.max(0, b - 2).toFixed(1)}" height="50" fill="var(--ring1)"/><rect x="${(40 + a + b + 2).toFixed(1)}" y="60" width="${Math.max(0, c - 2).toFixed(1)}" height="50" rx="4" fill="var(--ring2)"/>`
        + G.t(40, 136, `Output ${fp(v.Po / 1e3)} kW`, { w: 700 }) + G.t(40, 156, `Core ${fp(v.Pi / 1e3)} kW · Copper ${fp(v.Pcu / 1e3)} kW`, { c: 'gv' }) + G.t(40, 196, `η = ${fp(v.eta)} %`, { w: 800, s: 22 }) + G.t(520, 196, `max ${fp(v.etam)} % at ${fp(v.xm)} % load`, { a: 'end', c: 'gv' }), 'Power split between output, core loss and copper loss'); },
