    o: [['A', 'Parallel paths A', '', v => v.wind === 'lap' ? v.P : 2], ['T', 'Torque T = PΦZI_a/(2πA)', 'N·m', v => v.P * v.phi * v.Z * v.Ia / (2 * PI * v.A)], ['Eb', 'Back EMF at N', 'V', v => v.P * v.phi * v.Z * v.N / (60 * v.A)], ['Pm', 'Power E_b I_a', 'W', v => v.Eb * v.Ia], ['Tchk', 'Check: P_m/ω', 'N·m', v => v.Pm / (2 * PI * v.N / 60)]],
