    cn: { w: 'Each current-carrying conductor in the pole flux feels a sideways force; all the forces act at the armature radius and add up to a torque.', y: 'F = BIl on every conductor; more current or more flux, more force.', s: ['Current per path: I_a/A.', 'Force per conductor ∝ B × current.', 'T = 0.159 PΦZI_a/A.'], a: 'Sizing a motor for a load torque; current-limited torque of a drive.', mk: ['Using 60 instead of 2π.'], sc: ['T ∝ Φ I_a.', 'T (N·m) = 9.55 E_b I_a/N.'] },
    rel: [['Ia', 'T', 'T ∝ Φ I_a.'], ['N', 'T', 'At a given current and flux the torque does not depend on the speed.'], ['phi', 'T', 'T ∝ Φ I_a.']],
