    if (o.rotor !== false) { const thr = o.thr; g += `<circle cx="${cx}" cy="${cy}" r="64" fill="var(--gcore)" stroke="var(--gline)" stroke-width="2"/>`; for (let k = 0; k < 12; k++) { const a = thr + k * PI / 6; g += `<circle cx="${(cx + 54 * Math.cos(a)).toFixed(1)}" cy="${(cy + 54 * Math.sin(a)).toFixed(1)}" r="${k ? 4.5 : 7}" fill="${k ? 'var(--gcu)' : 'var(--lxo)'}"/>`; } }
    const L = 78 * Fm / 1.5; g += G.arrow(cx - L * Math.cos(-ang) * 0.6, cy - L * Math.sin(-ang) * 0.6, cx + L * Math.cos(-ang), cy + L * Math.sin(-ang), 'var(--lxp)', 4) + G.t(cx + (L + 14) * Math.cos(-ang), cy + (L + 14) * Math.sin(-ang) + 4, 'N', { a: 'middle', w: 800, f: 'var(--lxp)' });
