    rel: [['f', 'Ns', 'N_s = 120f/P: proportional to frequency.'], ['P', 'Ns', 'N_s = 120f/P: more poles, slower field.'], ['ib', 'Fmin', 'Unbalance makes the field elliptical; its smallest value shrinks as phase B weakens.']],
